edits.newText:
class VoidBrowserController {
  Future<void> Function(String path)? _scrollToTrack;

  /// Whether the current now-playing track row is outside the visible
  /// scroll-region of the browser list.
  ///
  /// Updated by [VoidBrowser] when mounted; defaults to `false` until the
  /// browser computes visibility.
  final ValueNotifier<bool> playingTrackOutsideVisibleRegion =
      ValueNotifier<bool>(false);

  /// Centre the row for [path] in view; no-op when the browser is unmounted.
  Future<void> scrollToTrack(String path) async =>
      await _scrollToTrack?.call(path);

  void dispose() {
    playingTrackOutsideVisibleRegion.dispose();
  }
}

